class Solution {
public:
    int kEmptySlots(vector<int>& bulbs, int k) {
        int n = bulbs.size();
        vector<int> day(n);
        for (int i = 0; i < n; ++i) {
            day[bulbs[i] - 1] = i + 1;
        }
        int answer = INT_MAX;
        int left = 0;
        int right = k + 1;
        while (right < n) {
            bool valid = true;
            for (int i = left + 1; i < right; ++i) {
                if (day[i] < day[left] || day[i] < day[right]) {
                    left = i;
                    right = i + k + 1;
                    valid = false;
                    break;
                }
            }
            if (valid) {
                answer = min(answer, max(day[left], day[right]));
                left = right;
                right = left + k + 1;
            }
        }
        return answer == INT_MAX ? -1 : answer;
    }
};
